import{_ as t,o as i,c as r,ai as e}from"./chunks/framework.ampVZV4B.js";const g=JSON.parse('{"title":"从身边挖掘真实需求","description":"","frontmatter":{},"headers":[],"relativePath":"ai/business/demand-mining.md","filePath":"ai/business/demand-mining.md"}'),l={name:"ai/business/demand-mining.md"};function n(s,a,d,o,h,p){return i(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="从身边挖掘真实需求" tabindex="-1">从身边挖掘真实需求 <a class="header-anchor" href="#从身边挖掘真实需求" aria-label="Permalink to “从身边挖掘真实需求”">​</a></h1><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>大多数副业死于第一步：需求是想出来的，不是找到的。「做一个 AI 帮你 XXX 的工具」这种开场，往往来自刷到别人做了什么，而不是真的有人在为这件事发愁。想出来的需求经不起一次追问——「谁会付钱？他现在怎么解决？愿意付多少？」三问之后多半哑火。</p><p>好消息是，真实需求从来不需要发明，它们就暴露在你每天已经身处的场景里：业务系统的工单、工作群的吐槽、同事的 Excel、外包客户反复提的修改。对在职工程师来说，<strong>你本身就是离需求最近的一批人</strong>。这篇讲的是把这些信号捞出来、筛出来的具体方法。</p><h2 id="拆解" tabindex="-1">拆解 <a class="header-anchor" href="#拆解" aria-label="Permalink to “拆解”">​</a></h2><h3 id="_1-三个信号源-痛感在哪里-需求就在哪里" tabindex="-1">1. 三个信号源：痛感在哪里，需求就在哪里 <a class="header-anchor" href="#_1-三个信号源-痛感在哪里-需求就在哪里" aria-label="Permalink to “1. 三个信号源：痛感在哪里，需求就在哪里”">​</a></h3><p><strong>信号源一：工单与反馈</strong></p><p>你维护的系统里，重复出现的工单就是需求。判断标准很简单：同一类问题每月出现 10 次以上，且每次都靠人肉处理——这就是一个「自动化/工具」需求。更妙的是，这类需求往往有明确的付费方（你所在的公司或客户），验证成本极低：先在内部做成提效工具，跑通了再想是否产品化。</p><p><strong>信号源二：群聊与吐槽</strong></p><p>工作群、行业群、外包合作群里，高频出现的抱怨是金矿：</p><ul><li>「每次都要手动整理这个表，烦死了」——流程自动化需求；</li><li>「客户又说要改这个，改一次半天」——工具/模板需求；</li><li>「这个东西怎么还没人做个好用的」——现有方案不满意的信号。</li></ul><p>记录方式不用复杂，开一个备忘录，听到吐槽就记一句原话 + 出现频率。<strong>原话比转述有价值</strong>，它直接就是未来 landing page 的文案。</p><p><strong>信号源三：自己重复做过三次的事</strong></p><p>任何你第三次手工重复做的事，都值得问一句：别人是否也重复？你的某次「顺手写的小脚本」，可能就是别人愿意付费的工具雏形。工程师的副业优势恰恰在于：<strong>你的业余产出物（脚本、配置、流程）本身就可以是产品</strong>。</p><h3 id="_2-真需求-vs-伪需求-三把尺子" tabindex="-1">2. 真需求 vs 伪需求：三把尺子 <a class="header-anchor" href="#_2-真需求-vs-伪需求-三把尺子" aria-label="Permalink to “2. 真需求 vs 伪需求：三把尺子”">​</a></h3><p>捞出信号后，用三把尺子筛：</p><table tabindex="0"><thead><tr><th>尺子</th><th>问法</th><th>伪需求的典型回答</th></tr></thead><tbody><tr><td>现有替代</td><td>他现在怎么解决的？</td><td>「没解决，就忍着」——可能是真空白，也可能是痛感不够</td></tr><tr><td>痛感强度</td><td>上次遇到是什么时候？多久遇到一次？</td><td>「好像挺久没遇到了」——低频到记不住</td></tr><tr><td>付费证据</td><td>他为解决它花过钱/时间吗？</td><td>从没花过，纯属「有也不错」</td></tr></tbody></table><p>最容易上当的是伪需求里最体面的一种：<strong>你自己觉得痛</strong>。你是工程师，你的时间值钱，你愿意为效率付费——但目标用户可能时薪是你的十分之一，他们选择忍。区分方法只有一个：<strong>找到三个和你处境不同的人，问他们同一个问题</strong>。三个人里两个说「我也有这个困扰且现在解不了」，才值得继续。</p><h3 id="_3-频次与付费意愿-两张快速判断表" tabindex="-1">3. 频次与付费意愿：两张快速判断表 <a class="header-anchor" href="#_3-频次与付费意愿-两张快速判断表" aria-label="Permalink to “3. 频次与付费意愿：两张快速判断表”">​</a></h3><p><strong>频次判断</strong>（决定这生意能不能做大）：</p><ul><li>每天/每周发生 → 可以做工具、做订阅；</li><li>每月发生 → 做一次性解决方案即可；</li><li>每年发生一次 → 除非客单价很高，否则不值得投入。</li></ul><p><strong>付费意愿判断</strong>（决定这生意能不能存在）：</p><ol><li>有预算的人是谁？（个人掏腰包 / 公司报销 / 平台分成）个人付费最冲动也最小额，公司付费流程长但客单高；</li><li>现有方案收费吗？市场已有付费产品 = 付费意愿已被验证，这<strong>不是坏事</strong>，反而说明不用教育市场；</li><li>能一句话说清 ROI 吗？「每月帮你省 4 小时」比「让工作更智能」的付费转化高一个数量级。</li></ol><p>一个务实的排序建议：<strong>先做「高频 + 已有付费先例 + 预算方明确」的需求</strong>，哪怕竞争者多；好需求被抢，远好过完美需求没人要。</p><h3 id="_4-一个把流程跑起来的每周习惯" tabindex="-1">4. 一个把流程跑起来的每周习惯 <a class="header-anchor" href="#_4-一个把流程跑起来的每周习惯" aria-label="Permalink to “4. 一个把流程跑起来的每周习惯”">​</a></h3><p>不需要专门「做调研」，把挖掘嵌进日常即可：</p><ul><li>每周花 20 分钟翻一遍备忘录里的吐槽记录，给出现频率 ≥ 2 次的条目加标记；</li><li>每月挑标记最多的一条，找 3 个不同处境的人聊 10 分钟（问现有解法和最近一次发生时间，不推销）；</li><li>聊完更新一句话结论，直接进入机会打分表（见「机会评估框架」）。</li></ul><p>整个习惯每周成本约半小时，坚持两个月就能积累出一张有据可依的需求清单——多数人缺的从来不是灵感，是把灵感落到纸面并持续追踪的机制。</p><h2 id="关键要点" tabindex="-1">关键要点 <a class="header-anchor" href="#关键要点" aria-label="Permalink to “关键要点”">​</a></h2><ul><li>需求不用发明：工单里的重复问题、群聊里的原话吐槽、自己重复三次的事，是最便宜的三个信号源；</li><li>记录用户原话，它同时是需求证据和未来营销文案；</li><li>三把尺子筛伪需求：现有替代、痛感频次、付费证据——「你自己觉得痛」不算数；</li><li>频次决定形态（高频做工具，低频做方案），付费方决定模式（个人看冲动，公司看 ROI）；</li><li>已有付费竞品是利好：说明市场教育完成，你要做的只是更好或更便宜。</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>从身边挖需求的本质，是把「我要做什么产品」的问题倒过来：先让市场把需求塞到你面前，你只做筛选。作为在职工程师，工单、群聊和自己的重复劳动就是现成的矿脉，整个过程不花一分钱。筛出来的东西未必能成，但至少保证了一点——你接下来投入的每个小时，都花在了一个有人真的在发愁的问题上。</p>',32)])])}const _=t(l,[["render",n]]);export{g as __pageData,_ as default};
